"""Versioned mechanics summaries plus the authoritative executable source bundle."""
import hashlib
import inspect
import re

from prediction.general_games.native import TA_ROOT
from prediction.general_games.evaluation.checks import ENGINE_FACTS
from .catalog import FAMILIES

RULES={
 'connect_four':('Empty rectangular public board. Players alternate dropping their own symbol into a nonfull column.', 'A drop occupies the lowest empty cell. Four contiguous own symbols horizontally, vertically or diagonally wins; full board without four draws.', 'Ends on a line, full board, or native invalid-action forfeit.'),
 'nim':('Public configured pile sizes; player 0 starts.', 'Remove a positive quantity from one nonempty pile, no more than its contents. Taking the final object wins.', 'Ends when all piles are empty or on native forfeit.'),
 'kuhn_poker':('Fresh J/Q/K cards sampled without replacement each round; each player sees only its own card and the public action tree. Each antes one.', 'Check/bet/call/fold traverse the native legal-action tree. Fold yields the pot to the other player; a showdown yields it to the higher card. Native bets and calls do not add extra chips.', 'After max_rounds, compare net chips. Ties draw. Native extra terminal ante applies equally to both.'),
 'liars_dice':('Each player starts with num_dice private fair d6 rolls. Counts remaining and resolved bids are public.', 'A valid bid raises quantity and/or face while neither decreases. Call counts exactly the named face across current dice; no wild faces. An incorrect challenger or failed bidder loses a die. Native rounds reroll remaining dice.', 'Last player with dice wins. Invalid actions follow the native die-loss handling rather than a generic label of cheating.'),
 'blind_auction':('Each receives configured starting_capital and own private item values generated by the native reset. Current bids are private until auction resolution.', 'Converse for the configured phase, then submit nonnegative item bids within remaining capital. Bids are recorded and all submitted amounts charged, even on lost items. Strictly higher bid wins; ties leave an item unallocated. Native source defines duplicate-bid and invalid-item handling.', 'After both bidding submissions, compare remaining capital plus own valuation of won items. Equal net worth draws.'),
 'negotiation':('Native reset generates private resource inventories and private per-resource values; an actor sees its own values/resources and public offers.', 'Submit a resource exchange; an affordable acceptance transfers requested and offered resources. Existing offers are cleared when not accepted, and a valid counteroffer can be created. Final standing compares gains in own inventory value.', 'Native max_turns or invalid-action termination; inventory-value gain determines win/draw/loss.'),
 'prisoners_dilemma':('Player 0 starts; each round has the configured conversation exchanges followed by private current decisions. Resolved decisions and scores become public.', 'Cooperate/cooperate yields cooperate_reward each; defect/cooperate gives defect_reward to the defector and sucker_reward to the cooperator; mutual defection gives mutual_defect_reward each. Any decision submission without [Defect] executes cooperation.', 'After num_rounds, strictly higher cumulative score wins; equal scores draw.'),
 'colonel_blotto':('Both players have num_total_units each round and num_fields named A onward. Current allocations remain private until the round resolves.', 'Allocate nonnegative integers summing exactly to the budget. Each field goes to the strictly larger allocation; equal fields tie. More field wins wins the round; more round wins wins the match. Native parsing supports its documented allocation syntax.', 'Native best-of-num_rounds match termination, including early clinching, or invalid-action forfeit.'),
 'pig_dice':('Both banked scores and current unbanked turn total are public. Native die draws are uniform integers 1–6.', 'Roll 2–6 adds to the turn total; roll 1 loses that unbanked total and passes the turn. Hold banks the total and passes. Reaching winning_score by banking wins.', 'Native max_turns is checked on turn rotation and can end by comparing banked scores; inspect source for exact boundary. Equal scores draw.'),
 'tower_of_hanoi':('Ordered configured stack begins on A; all towers public.', 'Move a top disk to a tower whose top disk is larger, or empty. The native parser may execute multiple bracketed moves in one response.', 'Complete ordered stack on C yields reward 1. Native max_turns/invalid handling may produce partial progress reward, which is not a full solution.'),
 'mastermind':('A private code is sampled from 1..num_numbers, with or without duplicates according to configuration.', 'Submit a code-length sequence. Black feedback counts correct positions; white counts remaining correct values with multiplicity. Past guesses and feedback are public to the solver.', 'Exact code yields reward 1; max_turns and invalid handling can terminate without a full solution.'),
 'wordle':('A hidden five-letter target is sampled from the installed noun-filtered en-basic lexicon; dictionaries and lexicon are fingerprinted.', 'Guess a valid word. Green matches positions; yellow matches unused remaining target letters, so duplicate counts are bounded. Native dictionary/repeated-guess checks apply.', 'All green gives reward 1. Guess limit and native invalid handling may yield partial credit; partial credit is not solved.'),
 'ultimatum':('Public pool and zero accumulated totals. Player 0 proposes first. Roles stay fixed unless alternate_roles is true.', 'An integer offer in [0,pool] gives the responder that amount and the proposer the remainder if accepted; rejection gives both zero. [Accept] takes precedence if accept and reject both occur. alternate_roles swaps proposer after each resolved round.', 'max_turns/2 resolved rounds; higher accumulated money wins, equal totals draw, or native invalid-action forfeit.'),
 'two_thirds':('Each round both players privately submit a guess in [min_guess,max_guess]; resolved history is public.', 'Target is two thirds of the arithmetic mean of both guesses. The strictly closer guess wins one point; equal distances give no point. The numeric parser accepts nonnegative decimal tokens.', 'After num_rounds compare points; equal totals draw, or native invalid-action forfeit.'),
 'secretary':('N independent U[0,1) values are generated. Only the current value, rounded to four decimal places, and the already observed prefix are shown; future values are hidden.', 'Exactly [accept] chooses the current value; exactly [continue] discards it. Continuing on the final value forces its selection. There is no recall. Native success uses underlying full-precision values.', 'Reward 1 iff the selected value is the maximum of all N; otherwise 0. Invalid-action forfeits are retained.'),
 'memory':('An even square board is a uniformly shuffled multiset containing two of every symbol. All unmatched identities are hidden until revealed.', 'Select two distinct unmatched positions. A matching pair scores one and remains visible; the same player moves again. A mismatch reveals both identities publicly, then hides them and rotates player. All reveal messages remain in history.', 'All pairs matched or native max_turns comparison ends the game. Higher pair count wins, equal counts draw, or native invalid-action forfeit.'),
}


def specification(game,session):
    family=game['family_id'];env=session.env;module=inspect.getmodule(type(env));path=inspect.getsourcefile(type(env))
    # No realized game_state enters this specification.
    state=env.state
    parsers={k:dict(pattern=v.pattern,flags=v.flags) for k,v in vars(env).items() if isinstance(v,re.Pattern)}
    initial,transition,termination=RULES[family]
    return dict(schema='native-mechanics-v2',family=family,initialization_and_information=initial,transitions_and_payoffs=transition,
        termination=termination,parser_patterns=parsers,
        invalid_handling=dict(state_class=type(state).__name__,consecutive_error_allowance=state.error_allowance,
            contract='A valid move resets the consecutive-error counter. A first invalid submission normally permits a retry; exhausting the native allowance terminates or applies the environment-specific penalty. Native environment overrides take precedence.'),
        opponent=FAMILIES[family]['opponent_policy'] or 'No opponent; single-player solver.',
        implementation_notes=ENGINE_FACTS.get(family,'See transitions, termination and exact parser patterns above.'),
        player_protocol='One focal LLM; temperature 0.7, requested reasoning low, full own native observation history, original normal/exploration system wording, 16384 output tokens. Native rules plus public constructor values are shown to the actor. These extra mechanics summaries and bot specifications are predictor context only.',
        external_limits=dict(total_actions=128,focal_actions=64,limit_outcome='censored; never relabeled as a native loss'),
        authoritative_sources=[dict(path=str(__import__('pathlib').Path(path).relative_to(TA_ROOT)),sha256=hashlib.sha256(__import__('pathlib').Path(path).read_bytes()).hexdigest()),
            *[dict(path=name,sha256=hashlib.sha256((TA_ROOT/name).read_bytes()).hexdigest()) for name in ('state.py','core.py')]],
        source_contract='The separately archived unmodified native source and scripted-opponent source are the complete executable specification. This normalized summary is a compact predictor rendering, not a substitute for the executable rules.')
